cash_flows = [-10000, 3000, 4000, 5000, 3000]

def npv(rate):
    return sum(cf / ((1 + rate) ** i) for i, cf in enumerate(cash_flows))

# Bisection method to find IRR
low, high = -0.99, 1.0
for _ in range(100):
    mid = (low + high) / 2
    if npv(mid) > 0:
        low = mid
    else:
        high = mid

irr = mid
print(f"{irr * 100:.1f}")

